# Phase 75 Qdrant API Test Script\n# Tests Qdrant search functionality without rebuilding\n\nparam(\n    [string]$QdrantUrl = \"http://localhost:6334\",\n    [string]$ApiKey = \"qdrant-key-phase75\",\n    [string]$CollectionName = \"r3_semantic_cache_phase75\"\n)\n\nWrite-Host \"\" -ForegroundColor Green\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"Phase 75 Qdrant API Test\" -ForegroundColor Green\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"\"\n\n# Test 1: Health Check\nWrite-Host \"[1/5] Testing Qdrant Health...\" -ForegroundColor Cyan\ntry {\n    $health = Invoke-RestMethod -Uri \"$QdrantUrl/health\" -Method Get -ErrorAction Stop\n    Write-Host \"✅ Health Check Passed\" -ForegroundColor Green\n    Write-Host \"   Status: $($health.status)\" -ForegroundColor Gray\n} catch {\n    Write-Host \"❌ Health Check Failed\" -ForegroundColor Red\n    Write-Host \"   Error: $($_.Exception.Message)\" -ForegroundColor Red\n    Write-Host \"   Make sure Qdrant is running: docker-compose -f docker-compose.phase75-standalone.yml up -d\" -ForegroundColor Yellow\n    exit 1\n}\n\n# Test 2: List Collections\nWrite-Host \"\"\nWrite-Host \"[2/5] Listing Collections...\" -ForegroundColor Cyan\ntry {\n    $collections = Invoke-RestMethod -Uri \"$QdrantUrl/collections\" -Method Get -ErrorAction Stop\n    Write-Host \"✅ Collections Retrieved\" -ForegroundColor Green\n    Write-Host \"   Count: $($collections.result.collections.Count)\" -ForegroundColor Gray\n    if ($collections.result.collections.Count -gt 0) {\n        foreach ($col in $collections.result.collections) {\n            Write-Host \"   - $($col.name)\" -ForegroundColor Gray\n        }\n    }\n} catch {\n    Write-Host \"❌ Failed to List Collections\" -ForegroundColor Red\n    Write-Host \"   Error: $($_.Exception.Message)\" -ForegroundColor Red\n}\n\n# Test 3: Create Collection (if not exists)\nWrite-Host \"\"\nWrite-Host \"[3/5] Creating Collection ($CollectionName)...\" -ForegroundColor Cyan\ntry {\n    $createPayload = @{\n        vectors = @{\n            size = 768\n            distance = \"Cosine\"\n        }\n    } | ConvertTo-Json\n    \n    $response = Invoke-RestMethod -Uri \"$QdrantUrl/collections/$CollectionName\" `\n        -Method Put `\n        -ContentType \"application/json\" `\n        -Body $createPayload `\n        -ErrorAction Stop\n    \n    Write-Host \"✅ Collection Created/Verified\" -ForegroundColor Green\n} catch {\n    if ($_.Exception.Response.StatusCode -eq 400) {\n        Write-Host \"✅ Collection Already Exists\" -ForegroundColor Green\n    } else {\n        Write-Host \"❌ Failed to Create Collection\" -ForegroundColor Red\n        Write-Host \"   Error: $($_.Exception.Message)\" -ForegroundColor Red\n    }\n}\n\n# Test 4: Insert Test Vector\nWrite-Host \"\"\nWrite-Host \"[4/5] Inserting Test Vector...\" -ForegroundColor Cyan\ntry {\n    # Generate random 768d vector\n    $vector = @()\n    for ($i = 0; $i -lt 768; $i++) {\n        $vector += [Math]::Round((Get-Random -Minimum -1000 -Maximum 1000) / 1000, 3)\n    }\n    \n    $pointId = Get-Random -Minimum 1 -Maximum 1000000\n    $insertPayload = @{\n        points = @(\n            @{\n                id = $pointId\n                vector = $vector\n                payload = @{\n                    content = \"Test chunk content\"\n                    file_path = \"test/file.ts\"\n                    chunk_id = \"test_chunk_0\"\n                    language = \"typescript\"\n                    timestamp = [int64](Get-Date -UFormat %s)\n                }\n            }\n        )\n    } | ConvertTo-Json -Depth 10\n    \n    $response = Invoke-RestMethod -Uri \"$QdrantUrl/collections/$CollectionName/points\" `\n        -Method Put `\n        -ContentType \"application/json\" `\n        -Body $insertPayload `\n        -ErrorAction Stop\n    \n    Write-Host \"✅ Test Vector Inserted\" -ForegroundColor Green\n    Write-Host \"   Point ID: $pointId\" -ForegroundColor Gray\n    Write-Host \"   Vector Dimension: 768\" -ForegroundColor Gray\n} catch {\n    Write-Host \"❌ Failed to Insert Vector\" -ForegroundColor Red\n    Write-Host \"   Error: $($_.Exception.Message)\" -ForegroundColor Red\n}\n\n# Test 5: Search Test\nWrite-Host \"\"\nWrite-Host \"[5/5] Testing Cosine Similarity Search...\" -ForegroundColor Cyan\ntry {\n    # Generate random query vector\n    $queryVector = @()\n    for ($i = 0; $i -lt 768; $i++) {\n        $queryVector += [Math]::Round((Get-Random -Minimum -1000 -Maximum 1000) / 1000, 3)\n    }\n    \n    $searchPayload = @{\n        vector = $queryVector\n        limit = 5\n        score_threshold = 0.5\n    } | ConvertTo-Json -Depth 10\n    \n    $results = Invoke-RestMethod -Uri \"$QdrantUrl/collections/$CollectionName/points/search\" `\n        -Method Post `\n        -ContentType \"application/json\" `\n        -Body $searchPayload `\n        -ErrorAction Stop\n    \n    Write-Host \"✅ Search Completed\" -ForegroundColor Green\n    Write-Host \"   Results Found: $($results.result.Count)\" -ForegroundColor Gray\n    \n    if ($results.result.Count -gt 0) {\n        foreach ($result in $results.result) {\n            Write-Host \"   - ID: $($result.id), Score: $($result.score)\" -ForegroundColor Gray\n        }\n    }\n} catch {\n    Write-Host \"❌ Search Failed\" -ForegroundColor Red\n    Write-Host \"   Error: $($_.Exception.Message)\" -ForegroundColor Red\n}\n\n# Summary\nWrite-Host \"\"\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"Test Summary\" -ForegroundColor Green\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"\"\nWrite-Host \"Qdrant URL: $QdrantUrl\" -ForegroundColor Gray\nWrite-Host \"Collection: $CollectionName\" -ForegroundColor Gray\nWrite-Host \"Vector Dimension: 768\" -ForegroundColor Gray\nWrite-Host \"\"\nWrite-Host \"Next Steps:\" -ForegroundColor Cyan\nWrite-Host \"1. Start Phase 75 stack: docker-compose -f docker-compose.phase75-standalone.yml up -d\" -ForegroundColor Yellow\nWrite-Host \"2. Run this test: .\\test-phase75-qdrant.ps1\" -ForegroundColor Yellow\nWrite-Host \"3. Check logs: docker logs qdrant-phase75-r3-cache\" -ForegroundColor Yellow\nWrite-Host \"\"\n"